#!/usr/bin/env python3
"""
Round 110c (culprits), 29 September 2026. Needs round 110b.

Planted, bought or captured: lawmakers, judges, rulers, officials and
companies found working for, paid by or tied to someone else, worldwide.
Replaces this chat's 109c and 109d, which were never uploaded.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 110c (29 September)\n\nNeeds round 110b. Tiles patch round110c_tiles.py beside it. Takes the place of\nthis chat\'s rounds 109c and 109d (never uploaded; do not upload them now).\n\n- capture_cases: "Planted, bought or captured", worldwide, every branch and\n  companies, every tier of proof marked (owner: all tiers, ties and allegations\n  included, each marked). Under Invasion of humans and Politics as a front.\n  Coloured by tier (court, inquiry, archive, admitted, served a spy service,\n  ties, settled with a regulator, alleged); the box gives the branch and who\n  they worked for.\n- Built by tiles scripts/capture.py (weekly): Wikidata office holders who\n  served a spy service or secret police, office holders and company staff\n  convicted of spying, treason, bribery and the like; Wikipedia\'s Venona list\n  and Mitrokhin article; secret-police collaborator categories on the cs, sk,\n  pl, de, ro and bg Wikipedias (placed via Wikidata citizenship); es.wikipedia\n  parapolitics lists; every SEC FCPA case, one point per country named; every\n  DOJ FCPA case since 1977 (chronological lists), at the court district\'s city;\n  about 60 compiled cases with sources (Colombia by name, LDP and the\n  Unification Church, Qatargate, NSICOP, US copy-paste bills, Stasi informers,\n  Garcia Luna, Noriega, kids-for-cash judges, Odebrecht in 12 countries, Babis).\n- Poland: tiles scripts/capture_ipn.py reads IPN\'s catalogue of people in\n  public office (katalog.bip.ipn.gov.pl/informacje/<n>) a slice a day,\n  resumable (capture/ipn_state.json); keeps TW/KO/agent registrations\n  (archive), lustration rulings of untrue declarations (court) and candidates\n  (alleged). capture.py merges capture/ipn.geojson.\n- Probes (Czech ABS registers, Slovak UPN regpro, one IPN entry) saved to tiles\n  probe/capture/ for a later round: match register entries to office holders by\n  name and birth date.\n- None of the tiles readers could be run from the sandbox: read\n  capture/build.json and capture/ipn_build.json after the first runs.\n- Script version app.js?v=1002.\n\n'
HEAD = "## Round 110c (29 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round110c: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 110b" not in text:
        sys.exit("round110c: round 110b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round110c: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round110c: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round110c: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 110b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
